import{_ as a,o as n,c as i,a5 as t}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Destructive agency Drive disconnect","description":"","frontmatter":{},"headers":[],"relativePath":"feature/customer-drive-disconnect/spec.md","filePath":"feature/customer-drive-disconnect/spec.md"}'),r={name:"feature/customer-drive-disconnect/spec.md"};function s(o,e,c,l,d,u){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="destructive-agency-drive-disconnect" tabindex="-1">Destructive agency Drive disconnect <a class="header-anchor" href="#destructive-agency-drive-disconnect" aria-label="Permalink to &quot;Destructive agency Drive disconnect&quot;">​</a></h1><h2 id="objective-user-story" tabindex="-1">Objective / user story <a class="header-anchor" href="#objective-user-story" aria-label="Permalink to &quot;Objective / user story&quot;">​</a></h2><p>Agency managers can deliberately delete the agency&#39;s BrandHub Drive resources and connect another Google account.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Owner/manager confirms a destructive warning covering every agency workspace, including trash and uploads. Never delete unrelated Drive files or system storage.</li><li>Disconnect fences Drive grants and OAuth callbacks before deletion. Durable disconnecting state survives failure/restart; retry resumes cleanup. Do not permit another connection until cleanup succeeds.</li><li>Delete tracked Drive objects (including moved objects), workspace folders and the agency root; tolerate 404. Retain credentials until cleanup is complete.</li><li>Tombstone USER_GDRIVE materials, fail upload sessions, release reserved and committed quota once, remove mappings and connection. Other providers/agencies remain unchanged. Existing external references may become unavailable; warn explicitly.</li><li>Repeated disconnect is harmless. New authorization after successful cleanup can choose another account.</li></ul><h2 id="ui-i18n" tabindex="-1">UI / i18n <a class="header-anchor" href="#ui-i18n" aria-label="Permalink to &quot;UI / i18n&quot;">​</a></h2><p>Use existing danger ConfirmDialog. Update workspace.agencyStorage.disconnectDescription, disconnectSuccess; add disconnectConfirm, disconnectPending, disconnectFailed to both vi/en workspace.json. Theme tokens and existing keyboard/mobile behavior remain.</p><h2 id="api-errors-states" tabindex="-1">API / errors / states <a class="header-anchor" href="#api-errors-states" aria-label="Permalink to &quot;API / errors / states&quot;">​</a></h2><p>DELETE existing workspace storage/drive route; status adds disconnecting boolean. Pending cleanup blocks authorize/complete; errors retain retry action. Missing connection returns success.</p><h2 id="out-of-scope-done" tabindex="-1">Out of scope / done <a class="header-anchor" href="#out-of-scope-done" aria-label="Permalink to &quot;Out of scope / done&quot;">​</a></h2><p>No migration of old files, no deletion of personal Drive outside BrandHub folders, no live destructive execution. Done when targeted backend/frontend checks pass or environment limitations are recorded.</p><h2 id="readiness-diagnostics" tabindex="-1">Readiness diagnostics <a class="header-anchor" href="#readiness-diagnostics" aria-label="Permalink to &quot;Readiness diagnostics&quot;">​</a></h2><p>When storage is unavailable, backend logs must identify disabled/missing environment variable names, invalid encryption key format/length, missing tables or disconnecting column. Never log configuration values, credentials or tokens. Public API stays unchanged.</p><h2 id="callback-diagnostics" tabindex="-1">Callback diagnostics <a class="header-anchor" href="#callback-diagnostics" aria-label="Permalink to &quot;Callback diagnostics&quot;">​</a></h2><p>Callback validation failures must log only reason, origin and boolean presence flags; never OAuth values or identity IDs. API failures log status and correlation identifiers only. UI remains unchanged; no cross-origin fallback or weakening actor validation.</p>',15)])])}const g=a(r,[["render",s]]);export{p as __pageData,g as default};
